import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import { useParams } from 'react-router-dom';

const FuelPageContainer = styled.div`
    padding: 20px;
    font-family: Arial, sans-serif;
`;

const Table = styled.table`
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
`;

const TableHeader = styled.th`
    border: 1px solid #ddd;
    padding: 8px;
    background-color: #f2f2f2;
`;

const TableCell = styled.td`
    border: 1px solid #ddd;
    padding: 8px;
`;

const Form = styled.form`
    display: flex;
    flex-direction: column;
    gap: 10px;
`;

const Input = styled.input`
    padding: 10px;
    border: 1px solid #ddd;
`;

const Button = styled.button`
    padding: 10px;
    border: none;
    background: #007BFF;
    color: white;
    cursor: pointer;
`;

const FuelPage = () => {
    const { lorryId } = useParams(); // ✅ Correctly fetching from URL
    const [fuelData, setFuelData] = useState([]);
    const [newFuel, setNewFuel] = useState({
        fill_date: '',
        bunk_name: '',
        total_amount: '',
        amount_paid: ''
    });

    const fetchFuelData = async () => {
        if (!lorryId) {
            console.error("🚨 Missing lorryId in URL.");
            return;
        }
        try {
            const response = await fetch(`http://localhost:5000/api/fuel/${lorryId}`);
            const data = await response.json();
            setFuelData(data);
        } catch (error) {
            console.error('Error fetching fuel data:', error);
        }
    };

    useEffect(() => {
        fetchFuelData();
    }, [lorryId]);

    const handleInputChange = (e) => {
        setNewFuel({ ...newFuel, [e.target.name]: e.target.value });
    };

    const handleAddFuel = async (e) => {
        e.preventDefault();
        if (!lorryId) {
            alert("🚨 lorryId is missing. Please verify your URL.");
            return;
        }
        try {
            const response = await fetch('http://localhost:5000/api/fuel/add', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    lorry_id: lorryId, // ✅ Ensure lorry_id is passed correctly
                    ...newFuel
                })
            });
            if (!response.ok) {
                throw new Error('Failed to add fuel data');
            }
            alert('Fuel details added successfully!');
            fetchFuelData();
        } catch (error) {
            console.error('Error adding fuel data:', error);
        }
    };

    return (
        <FuelPageContainer>
            <h1>Fuel Details for Lorry ID: {lorryId}</h1>
            <Form onSubmit={handleAddFuel}>
                <Input type="date" name="fill_date" value={newFuel.fill_date} onChange={handleInputChange} required />
                <Input type="text" name="bunk_name" value={newFuel.bunk_name} onChange={handleInputChange} required />
                <Input type="number" name="total_amount" value={newFuel.total_amount} onChange={handleInputChange} required />
                <Input type="number" name="amount_paid" value={newFuel.amount_paid} onChange={handleInputChange} required />
                <Button type="submit">Add Fuel Record</Button>
            </Form>
            <Table>
                <thead>
                    <tr>
                        <TableHeader>Date</TableHeader>
                        <TableHeader>Bunk Name</TableHeader>
                        <TableHeader>Total Amount</TableHeader>
                        <TableHeader>Amount Paid</TableHeader>
                        <TableHeader>Remaining Amount</TableHeader>
                    </tr>
                </thead>
                <tbody>
                    {fuelData.length > 0 ? fuelData.map((fuel, index) => (
                        <tr key={index}>
                            <TableCell>{fuel.fill_date}</TableCell>
                            <TableCell>{fuel.bunk_name}</TableCell>
                            <TableCell>{fuel.total_amount}</TableCell>
                            <TableCell>{fuel.amount_paid}</TableCell>
                            <TableCell>{fuel.remaining_amount}</TableCell>
                        </tr>
                    )) : (
                        <tr><TableCell colSpan="5">No fuel records found.</TableCell></tr>
                    )}
                </tbody>
            </Table>
        </FuelPageContainer>
    );
};

export default FuelPage;
